\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential

\begin{document}

 	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
 	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
 	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
 	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
 	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
 	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
 	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

 	\pagestyle{empty} %% IMPORTANT


\begin{tikzpicture}

\def\a{0};
\def\b{4};
\def\c{0};
\def\d{4};


 	\begin{axis}[
 	legend cell align={left},
 	tick label style={font=\footnotesize},
 	label style={font=\small},
 	legend pos=outer north east,
 	legend style={font=\footnotesize},
 	tick style={draw=black},
 	axis line style = thick,
 	axis y line = middle,
 	axis x line = middle,
 	axis equal,
 	%grid = both,
 	xmin = -1,
 	xmax = 5,
 	ymin = -1,
 	ymax = 5,
 	xtick = {\a,...,\b},
 	ytick = {\c,...,\d},
 	xlabel = $x$,
 	ylabel = {$y$},
        xticklabels={,,2,,4},
       yticklabels={,,2,,4},
 	xlabel style={below right},
 	ylabel style={above left},
 	every axis x label/.style={
 		at={(ticklabel* cs:1.02)},anchor=west,},
 	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
 	]


	%%% Region
	\foreach \i in {\a,...,\b}
	{
		\edef\temp{\noexpand\draw[thin, gray, dashed] (axis cs:2*\i-\a,\c) -- (axis cs:2*\i-\a,\d);}
    	\temp		
	};
	\foreach \j in {\c,...,\d}
	{
		\edef\temp{\noexpand\draw[thin, gray, dashed] (axis cs:\a,2*\j-\c) -- (axis cs:\b,2*\j-\c);}
    	\temp		
	};

	\draw[deepskyblue, very thick, fill=deepskyblue!30, fill opacity=0.5] (axis cs:\a,\c) rectangle (axis cs:\b,\d)
		node[above right, deepskyblue, fill opacity=1] at (axis cs:\b,\d) {$R$};

	\pgfmathtruncatemacro{\bb}{\b-3};
	\pgfmathtruncatemacro{\dd}{\d-3};

	\foreach [count=\ni] \i in {\a,...,\bb}
	{
		\foreach [count=\nj] \j in {\c,...,\dd}
		{
			\edef\temp{\noexpand\node[] at (axis cs:{2*\i-\a+1},{2*\j-\c+1}) {$R_{\ni \nj}$};}
			\temp
		};
	};

	%%% Dots
%	\node[circle, draw=none, fill=blue, inner sep=1.5pt] at (axis cs:0,0) {};
%	\node[circle, draw=none, fill=blue, inner sep=1.5pt] at (axis cs:2,0) {};
%	\node[circle, draw=none, fill=blue, inner sep=1.5pt] at (axis cs:0,2) {};
%	\node[circle, draw=none, fill=blue, inner sep=1.5pt] at (axis cs:2,2) {};

 	%%% Red squares
\node[rectangle, xshift=-2pt, yshift=-2pt, fill=red, inner sep=2pt,label={[below left, yshift=0pt]:{\small \color{red} min}}] at (axis cs:2,2) {};
\node[rectangle, xshift=-2pt, yshift=-2pt, fill=red, inner sep=2pt,label={[below left, yshift=0pt]:{\small \color{red} min}}] at (axis cs:4,2) {};
\node[rectangle, xshift=-2pt, yshift=-2pt, fill=red, inner sep=2pt,label={[below left, yshift=0pt]:{\small \color{red} min}}] at (axis cs:2,4) {};
\node[rectangle, xshift=-2pt, yshift=-2pt, fill=red, inner sep=2pt,label={[below left, yshift=0pt]:{\small \color{red} min}}] at (axis cs:4,4) {};



\end{axis}
\end{tikzpicture}
